// ---------------------------------------------------------------------------
// dates.js — timezone-safe date/time helpers.
// All dates in the Sheet are plain text "YYYY-MM-DD", times are "HH:MM" (24h).
// This file is compiled into n8n Code nodes by scripts/build.js, so it must be
// plain JavaScript with no imports (the strip blocks are removed at build time).
// ---------------------------------------------------------------------------

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function pad2(n) {
  return String(n).padStart(2, '0');
}

/** Today's date (YYYY-MM-DD) in the clinic's timezone. */
function todayIn(tz, now) {
  const d = now instanceof Date ? now : new Date();
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(d);
}

/** Current time (HH:MM, 24h) in the clinic's timezone. */
function timeIn(tz, now) {
  const d = now instanceof Date ? now : new Date();
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(d);
  const h = parts.find((p) => p.type === 'hour').value;
  const m = parts.find((p) => p.type === 'minute').value;
  return pad2(h) + ':' + pad2(m);
}

function isIsoDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y, m, d] = s.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

/** Add n calendar days to an ISO date string. */
function addDays(iso, n) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

/** Whole days from iso a to iso b (b - a). */
function daysBetween(a, b) {
  const ta = Date.parse(a + 'T00:00:00Z');
  const tb = Date.parse(b + 'T00:00:00Z');
  return Math.round((tb - ta) / 86400000);
}

function weekdayName(iso) {
  return WEEKDAYS[new Date(iso + 'T00:00:00Z').getUTCDay()];
}

/**
 * Normalise whatever a form / Google Sheet gives us into YYYY-MM-DD.
 * Handles: "2026-11-18", "2026-11-18T00:00:00.000Z", "18/11/2026", "18-11-2026",
 * "11/18/2026" (only when order === 'MDY'), and Google serial numbers (45980).
 * Returns '' when it cannot be parsed.
 */
function normalizeDate(value, order) {
  if (value === null || value === undefined || value === '') return '';
  if (typeof value === 'number' && value > 20000 && value < 80000) {
    // Google Sheets / Excel serial date (days since 1899-12-30)
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString().slice(0, 10);
  }
  const s = String(value).trim();
  const iso = s.slice(0, 10);
  if (isIsoDate(iso)) return iso;
  const m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const y = m[3];
    const [day, month] = order === 'MDY' ? [b, a] : [a, b];
    const out = y + '-' + pad2(month) + '-' + pad2(day);
    return isIsoDate(out) ? out : '';
  }
  return '';
}

/**
 * Normalise a time into HH:MM (24h). Accepts "9:5", "09:05", "17:30",
 * "5:30 PM", "5 pm", "17:30:00", and Sheets day-fractions (0.729166 = 17:30).
 */
function normalizeTime(value) {
  if (value === null || value === undefined || value === '') return '';
  if (typeof value === 'number' && value >= 0 && value < 1) {
    const total = Math.round(value * 24 * 60);
    return pad2(Math.floor(total / 60)) + ':' + pad2(total % 60);
  }
  const s = String(value).trim().toLowerCase();
  const m = s.match(/^(\d{1,2})(?:[:.](\d{1,2}))?(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return '';
  let h = Number(m[1]);
  const min = Number(m[2] || 0);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  if (h > 23 || min > 59) return '';
  return pad2(h) + ':' + pad2(min);
}

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function fromMinutes(total) {
  return pad2(Math.floor(total / 60)) + ':' + pad2(total % 60);
}

/** "2026-11-18" -> "18 Nov 2026" */
function displayDate(iso) {
  if (!isIsoDate(iso)) return iso || '';
  const [y, m, d] = iso.split('-').map(Number);
  return d + ' ' + MONTHS[m - 1] + ' ' + y;
}

/** "17:30" -> "5:30 PM" */
function displayTime(hhmm) {
  const t = normalizeTime(hhmm);
  if (!t) return hhmm || '';
  let [h, m] = t.split(':').map(Number);
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 === 0 ? 12 : h % 12;
  return h + ':' + pad2(m) + ' ' + ampm;
}

// ---------------------------------------------------------------------------
// sheet.js — the Appointments tab schema and row cleanup.
// Depends on: dates.js
// ---------------------------------------------------------------------------

// Exact header row of the "Appointments" tab (A..O). n8n matches by name —
// never rename these in a client's sheet.
const APPOINTMENT_COLUMNS = [
  'appointment_id', 'patient_name', 'phone', 'doctor', 'appt_date', 'appt_time',
  'visit_type', 'status', 'payment_status', 'amount_paid', 'payment_mode',
  'follow_up_date', 'whatsapp_consent', 'last_reminder_date', 'booked_on',
];

const STATUS = { BOOKED: 'Booked', COMPLETED: 'Completed', NO_SHOW: 'No-show', CANCELLED: 'Cancelled' };

/**
 * Google Sheets can hand back numbers, formatted dates or stray spaces if a
 * receptionist typed into the sheet by hand. Clean every row before using it.
 */
function normalizeRow(raw, config) {
  const order = (config && config.locale && config.locale.sheet_date_order) || 'DMY';
  const r = {};
  for (const col of APPOINTMENT_COLUMNS) {
    const v = raw[col];
    r[col] = v === undefined || v === null ? '' : typeof v === 'string' ? v.trim() : v;
  }
  r.appointment_id = String(r.appointment_id).toUpperCase();
  r.phone = String(r.phone).replace(/\D/g, '');
  r.appt_date = normalizeDate(r.appt_date, order);
  r.appt_time = normalizeTime(r.appt_time);
  r.follow_up_date = normalizeDate(r.follow_up_date, order);
  r.last_reminder_date = normalizeDate(r.last_reminder_date, order);
  r.booked_on = normalizeDate(r.booked_on, order);
  r.amount_paid = r.amount_paid === '' ? '' : Number(r.amount_paid) || 0;
  r.status = canonicalStatus(r.status);
  if (raw.row_number !== undefined) r.row_number = raw.row_number;
  return r;
}

function canonicalStatus(s) {
  const k = String(s || '').toLowerCase().replace(/[\s_-]/g, '');
  if (k === 'booked' || k === '') return STATUS.BOOKED;
  if (k === 'completed' || k === 'done') return STATUS.COMPLETED;
  if (k === 'noshow') return STATUS.NO_SHOW;
  if (k === 'cancelled' || k === 'canceled') return STATUS.CANCELLED;
  return String(s);
}

/** Only rows that actually are appointments (skip blank / half-typed lines). */
function cleanRows(items, config) {
  return items
    .map((r) => normalizeRow(r, config))
    .filter((r) => r.appointment_id && r.appt_date);
}

/** Full 15-column object with '' defaults — what we append to the sheet. */
function toSheetRow(partial) {
  const out = {};
  for (const col of APPOINTMENT_COLUMNS) out[col] = partial[col] === undefined ? '' : partial[col];
  return out;
}

// ---------------------------------------------------------------------------
// report.js — the doctor's end-of-day summary (counts + money, no patient names).
// Depends on: dates.js, sheet.js
// ---------------------------------------------------------------------------

function sumPaid(rows) {
  return rows.reduce((s, r) => s + (r.payment_status === 'Paid' ? Number(r.amount_paid) || 0 : 0), 0);
}

function buildDailyReport(rows, config, now) {
  const tz = config.locale.timezone;
  const cur = config.locale.currency || 'Rs';
  const today = todayIn(tz, now);
  const tomorrow = addDays(today, 1);

  const todays = rows.filter((r) => r.appt_date === today && r.status !== STATUS.CANCELLED);
  const done = todays.filter((r) => r.status === STATUS.COMPLETED);
  const noShow = todays.filter((r) => r.status === STATUS.NO_SHOW);
  const open = todays.filter((r) => r.status === STATUS.BOOKED);
  const cancelledToday = rows.filter((r) => r.appt_date === today && r.status === STATUS.CANCELLED);
  const collection = sumPaid(done);
  const pending = rows.filter((r) => r.status === STATUS.COMPLETED && r.payment_status === 'Pending');
  const stale = rows.filter((r) => r.status === STATUS.BOOKED && r.appt_date < today);
  const tmr = rows
    .filter((r) => r.appt_date === tomorrow && r.status === STATUS.BOOKED)
    .sort((a, b) => a.appt_time.localeCompare(b.appt_time));
  const newBookings = rows.filter((r) => r.booked_on === today);
  const followUpsTomorrow = rows.filter((r) => r.status === STATUS.COMPLETED && r.follow_up_date === tomorrow);

  const doctors = [...new Set(todays.concat(tmr).map((r) => r.doctor))].sort();
  const byDoctor = doctors.map((d) => ({
    doctor: d,
    total: todays.filter((r) => r.doctor === d).length,
    completed: done.filter((r) => r.doctor === d).length,
    no_show: noShow.filter((r) => r.doctor === d).length,
    collection: sumPaid(done.filter((r) => r.doctor === d)),
    tomorrow: tmr.filter((r) => r.doctor === d).length,
  }));

  const clinic = (config.client && config.client.clinic_name) || 'Clinic';
  const lines = [
    clinic + ' — report for ' + displayDate(today),
    '',
    'TODAY',
    'Appointments: ' + todays.length + '  (Completed ' + done.length + ' | No-show ' + noShow.length + ' | Not updated ' + open.length + ')',
    'Cancelled: ' + cancelledToday.length + '   New bookings taken today: ' + newBookings.length,
    'Collection: ' + cur + ' ' + collection,
    '',
    'PENDING',
    'Completed visits with payment pending: ' + pending.length,
    'Old bookings never updated (before today): ' + stale.length,
    '',
    'TOMORROW (' + displayDate(tomorrow) + ')',
    'Booked: ' + tmr.length + (tmr.length ? '  (first at ' + displayTime(tmr[0].appt_time) + ')' : ''),
    'Follow-ups due: ' + followUpsTomorrow.length,
  ];
  if (byDoctor.length > 1) {
    lines.push('', 'BY DOCTOR');
    for (const d of byDoctor) {
      lines.push(d.doctor + ': today ' + d.total + ' (done ' + d.completed + ', no-show ' + d.no_show + '), ' + cur + ' ' + d.collection + ', tomorrow ' + d.tomorrow);
    }
  }
  if (open.length) lines.push('', 'Note: ' + open.length + ' of today\'s visits are still "Booked" — reception should fill the Visit Update form.');

  const text = lines.join('\n');
  const html = '<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5">'
    + text.split('\n').map((l) => (/^(TODAY|PENDING|TOMORROW|BY DOCTOR)/.test(l)
      ? '<b>' + escapeHtml(l) + '</b>' : escapeHtml(l))).join('<br>')
    + '</div>';

  return {
    date: today,
    display_date: displayDate(today),
    total: todays.length,
    completed: done.length,
    no_show: noShow.length,
    not_updated: open.length,
    cancelled: cancelledToday.length,
    new_bookings: newBookings.length,
    collection,
    pending: pending.length,
    stale: stale.length,
    tomorrow: tmr.length,
    follow_ups_tomorrow: followUpsTomorrow.length,
    by_doctor: byDoctor,
    subject: clinic + ' report ' + displayDate(today) + ': ' + todays.length + ' visits, ' + cur + ' ' + collection,
    text,
    html,
  };
}

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

